package net.civeira.phylax.features.access.consentpurpose.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.access.consentpurpose.application.visibility.ConsentPurposeVisibilityCheck;

public class TenantAccesible {

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param filter
   */
  public void filterVisibles(@Observes ConsentPurposeVisibilityCheck filter) {
    Actor actor = filter.getActor();
    if (!(actor.hasScope("platform:global_access"))) {
      filter.peek(fl -> fl.setTenantAccesible(actor.getTenant().orElse(null)));
    }
  }
}
